import * as net from 'net';
import * as crypto from 'crypto';

// Circuit breaker states
enum CircuitState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN'
}

interface CircuitBreakerConfig {
  failureThreshold: number;
  recoveryTimeout: number;
  halfOpenRequests: number;
}

class CircuitBreaker {
  private state: CircuitState = CircuitState.CLOSED;
  private failures: number = 0;
  private lastFailureTime: number = 0;
  private config: CircuitBreakerConfig;

  constructor(config: CircuitBreakerConfig) {
    this.config = config;
  }

  canExecute(): boolean {
    if (this.state === CircuitState.CLOSED) return true;
    if (this.state === CircuitState.OPEN) {
      const elapsed = Date.now() - this.lastFailureTime;
      if (elapsed >= this.config.recoveryTimeout) {
        this.state = CircuitState.HALF_OPEN;
        return true;
      }
      return false;
    }
    return true;
  }

  recordSuccess(): void {
    this.failures = 0;
    this.state = CircuitState.CLOSED;
  }

  recordFailure(): void {
    this.failures++;
    this.lastFailureTime = Date.now();
    if (this.failures >= this.config.failureThreshold) {
      this.state = CircuitState.OPEN;
    }
  }
}

// Serialization context for email metadata
interface EmailMetadata {
  messageId: string;
  from: string;
  to: string[];
  subject: string;
  customHeaders: Map<string, string>;
  priority: number;
}

// Header encoding strategies
class HeaderEncoder {
  // RFC 2047 encoded-word encoding for non-ASCII
  static encodeWord(value: string): string {
    if (/^[\x20-\x7E]*$/.test(value)) {
      return value;
    }
    const encoded = Buffer.from(value, 'utf-8').toString('base64');
    return `=?UTF-8?B?${encoded}?=`;
  }

  // Fold long header lines per RFC 5322
  static foldHeader(name: string, value: string): string {
    const line = `${name}: ${value}`;
    if (line.length <= 78) return line;
    const chunks: string[] = [];
    let remaining = line;
    while (remaining.length > 76) {
      let breakPoint = remaining.lastIndexOf(' ', 76);
      if (breakPoint <= 0) breakPoint = 76;
      chunks.push(remaining.substring(0, breakPoint));
      remaining = ' ' + remaining.substring(breakPoint).trimStart();
    }
    chunks.push(remaining);
    return chunks.join('\r\n');
  }
}

// Serializer that converts metadata to wire format
class EmailSerializer {
  private breaker: CircuitBreaker;
  private serializationCache: Map<string, string>;

  constructor(breaker: CircuitBreaker) {
    this.breaker = breaker;
    this.serializationCache = new Map();
  }

  // Sanitize individual header value - removes injection vectors
  private sanitizeHeaderValue(value: string): string {
    // Remove null bytes
    let sanitized = value.replace(/\x00/g, '');
    // Strip CR and LF characters entirely to prevent header injection
    sanitized = sanitized.replace(/[\r\n]/g, '');
    // Collapse whitespace sequences
    sanitized = sanitized.replace(/[\t ]{2,}/g, ' ');
    return sanitized;
  }

  // Validate header name per RFC 5322
  private isValidHeaderName(name: string): boolean {
    return /^[!-9;-~]+$/.test(name);
  }

  // Core serialization - produces header block
  serialize(metadata: EmailMetadata): string {
    if (!this.breaker.canExecute()) {
      throw new Error('Circuit breaker is open - serialization unavailable');
    }

    try {
      const cacheKey = crypto.createHash('sha256')
        .update(JSON.stringify({
          id: metadata.messageId,
          from: metadata.from,
          to: metadata.to,
          subject: metadata.subject
        }))
        .digest('hex');

      if (this.serializationCache.has(cacheKey)) {
        this.breaker.recordSuccess();
        return this.serializationCache.get(cacheKey)!;
      }

      const headers: string[] = [];

      // Standard headers with encoding
      headers.push(HeaderEncoder.foldHeader('Message-ID', `<${this.sanitizeHeaderValue(metadata.messageId)}>`));
      headers.push(HeaderEncoder.foldHeader('From', HeaderEncoder.encodeWord(this.sanitizeHeaderValue(metadata.from))));
      headers.push(HeaderEncoder.foldHeader('To', metadata.to.map(t => HeaderEncoder.encodeWord(this.sanitizeHeaderValue(t))).join(', ')));
      headers.push(HeaderEncoder.foldHeader('Subject', HeaderEncoder.encodeWord(this.sanitizeHeaderValue(metadata.subject))));
      headers.push(HeaderEncoder.foldHeader('X-Priority', String(Math.max(1, Math.min(5, metadata.priority)))));

      // Custom headers - apply sanitization
      for (const [name, value] of metadata.customHeaders) {
        if (!this.isValidHeaderName(name)) continue;
        const sanitizedValue = this.sanitizeHeaderValue(value);
        // Apply folding which handles the line structure
        headers.push(HeaderEncoder.foldHeader(name, sanitizedValue));
      }

      const result = headers.join('\r\n') + '\r\n';
      this.serializationCache.set(cacheKey, result);
      this.breaker.recordSuccess();
      return result;
    } catch (err) {
      this.breaker.recordFailure();
      throw err;
    }
  }
}

// Transport layer that sends serialized email
class SmtpTransport {
  private serializer: EmailSerializer;

  constructor(serializer: EmailSerializer) {
    this.serializer = serializer;
  }

  async sendEmail(metadata: EmailMetadata, body: string): Promise<void> {
    const headerBlock = this.serializer.serialize(metadata);
    // The header block is joined with body using blank line separator
    const message = headerBlock + '\r\n' + body;
    // In production this would go to an SMTP socket
    console.log('Sending message:', message.length, 'bytes');
  }
}

// Factory function
export function createEmailPipeline(): SmtpTransport {
  const breaker = new CircuitBreaker({
    failureThreshold: 5,
    recoveryTimeout: 30000,
    halfOpenRequests: 2
  });
  const serializer = new EmailSerializer(breaker);
  return new SmtpTransport(serializer);
}
